implementation_bundle.trigger_sql:
create or replace function ops.fn_wip_touch_updated() returns trigger as $$ begin new.updated_at = now(); return new; end; $$ language plpgsql;
drop trigger if exists trg_wip_touch_updated on ops.wip_commands;
create trigger trg_wip_touch_updated before update on ops.wip_commands for each row execute function ops.fn_wip_touch_updated();

create or replace function ops.enqueue_pen_expansion(p_wip_id uuid) returns void as $$ begin insert into audit.log(event_type, entity_type, entity_id, evidence_status, metadata) values ('WIP_ENQUEUE_PEN_EXPANSION','ops.wip_commands',p_wip_id::text,'PARTIAL',jsonb_build_object('receipt_required',true,'event_driven',true)) on conflict do nothing; end; $$ language plpgsql;

create or replace function ops.fn_wip_trigger() returns trigger as $$ begin perform ops.enqueue_pen_expansion(new.id); return new; end; $$ language plpgsql;
drop trigger if exists trg_wip_on_insert on ops.wip_commands;
create trigger trg_wip_on_insert after insert on ops.wip_commands for each row execute function ops.fn_wip_trigger();
